DROP TABLE IF EXISTS `v_monthly_player_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`dominues_apiback35`@`localhost` SQL SECURITY DEFINER VIEW `v_monthly_player_stats`  AS SELECT `u`.`id` AS `user_id`, `u`.`name` AS `player_name`, year(`gr`.`created_at`) AS `year`, month(`gr`.`created_at`) AS `month`, count(`gr`.`id`) AS `total_games`, sum((case when (`gr`.`is_winner` = 1) then 1 else 0 end)) AS `wins`, sum((case when (`gr`.`is_winner` = 0) then 1 else 0 end)) AS `losses`, round(((sum((case when (`gr`.`is_winner` = 1) then 1 else 0 end)) / count(`gr`.`id`)) * 100),2) AS `win_rate`, sum((case when (`gr`.`is_winner` = 1) then `gr`.`winner_amount` else 0 end)) AS `total_earned`, coalesce((select sum(abs(`gt`.`amount`)) from `game_transactions` `gt` where ((`gt`.`user_id` = `u`.`id`) and (`gt`.`transaction_type` = 'entry_fee') and (year(`gt`.`created_at`) = year(`gr`.`created_at`)) and (month(`gt`.`created_at`) = month(`gr`.`created_at`)))),0) AS `total_bet`, (sum((case when (`gr`.`is_winner` = 1) then `gr`.`winner_amount` else 0 end)) - coalesce((select sum(abs(`gt`.`amount`)) from `game_transactions` `gt` where ((`gt`.`user_id` = `u`.`id`) and (`gt`.`transaction_type` = 'entry_fee') and (year(`gt`.`created_at`) = year(`gr`.`created_at`)) and (month(`gt`.`created_at`) = month(`gr`.`created_at`)))),0)) AS `net_profit` FROM (`users` `u` join `game_results` `gr` on((`u`.`id` = `gr`.`user_id`))) WHERE (`gr`.`created_at` is not null) GROUP BY `u`.`id`, `u`.`name`, year(`gr`.`created_at`), month(`gr`.`created_at`) ORDER BY year(`gr`.`created_at`) DESC, month(`gr`.`created_at`) DESC, count(`gr`.`id`) DESC ;

